import{z as c,x as E,o,c as A,q as t,j as i,D as s,d as r,s as d,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"acquire / release","description":"","frontmatter":{"title":"acquire / release","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/acquire-release.md","filePath":"cs/acquire-release.md","lastUpdated":1791413859000}'),p={name:"cs/acquire-release.md"};function u(m,e,B,q,h,f){const l=E("Mermaid");return o(),A("div",null,[e[2]||(e[2]=t('<h1 id="acquire-release" tabindex="-1">acquire / release <a class="header-anchor" href="#acquire-release" aria-label="Permalink to &quot;acquire / release&quot;">​</a></h1><div class="epigraph"><p>释放之前的写必须在锁释放这一刀之前对全局可见；获取之后的读必须在锁获取这一刀之后才开始。不必对全世界做全序栅栏。</p><footer>—— 据 Boehm and Adve, Foundations of the C++ Concurrency Memory Model, PLDI 2008；SPARC RMO 整理</footer></div><p><a href="/cs/atomic-cache-impl">上一课</a> 保证单个地址的 RMW 不被切开。程序员写互斥时还需要：<strong>解锁之前对共享数据的 store，要被下一位加锁成功的人的 load 看见。</strong> <a href="/cs/mesi-protocol">MESI</a> 不管两个地址之间的顺序。本课不重做 cache lock。缺口是<strong>acquire/release：比 seq-cst 全栅栏弱、比 relaxed 强的单向屏障。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>核 A：<code>data=1; unlock</code>。核 B：<code>lock; x=data</code>。若 <code>unlock</code> 的 store 与 <code>data</code> 的 store 在写缓冲里重排，B 可能看到锁已开、<code>data</code> 仍是 0。seq-cst fence 能修，但把无关的访存也挡住，<a href="/cs/mlp-memory-parallelism">MLP</a> 与 store 缓冲收益尽失。缺口不是更重的原子，而是<strong>释放：此前写不能越过释放；获取：此后读不能越过获取。</strong></p><p><span class="marginnote">C++11 / RISC-V 的 <code>release</code>/<code>acquire</code>、ARM 的 <code>dmb ishld</code> 一类，都是这个单向约束。x86 TSO 对 store 已经很强，许多释放几乎免费，获取仍要限制 store 前的 load 重排——实现上常已满足。</span></p><p><span class="marginnote">直觉类比：release 像发车前「把所有已装箱的货物先装上车」——它之前写的每一件都必须先出去；acquire 像「签收之后才开始拆箱」——它之后的读不许提前翻墙。这一刀把时间切成两半，两侧的访存不能越境。</span></p><p><span class="marginnote">为什么重要：没有这对语义，核 A 写完 data=1 再解锁，核 B 可能拿到锁却读回旧值 0——锁形同虚设。配上 release 解锁、acquire 加锁，B 只要加锁成功就必然看见 A 解锁前的所有写，共享数据本身用普通访存即可。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>微结构：release store 在 SQ 里等到更年长的 store 都变成一致性可见（drain 到某一点）再发出；acquire load 之后的访存等该 load 完成（至少数据返回且获得足够权限）。不必等全世界的无关行。与 <a href="/cs/write-combining">写合并</a>：WC 区域的 drain 规则更严，release 往往强制冲刷 WCB。</p>',10)),(o(),i(n,null,{default:s(()=>[d(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E6%9B%B4%E5%B9%B4%E9%95%BF%E7%9A%84%20store%22%5D%20--%3E%20REL%5B%22release%22%5D%0A%20%20REL%20--%3E%20UNL%5B%22%E9%94%81%E5%AD%97%E5%8F%AF%E8%A7%81%22%5D%0A%20%20ACQ%5B%22acquire%20%E9%94%81%E5%AD%97%22%5D%20--%3E%20LD%5B%22%E6%9B%B4%E5%B9%B4%E8%BD%BB%E7%9A%84%20load%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,[r("这是内存模型与 cache 协议的接口：协议提供单行上的「可见」，模型把多行用 acquire/release 串起来。乱序核的 "),a("a",{href:"/cs/lsq-disambiguation"},"LSQ"),r(" 必须禁止跨越这些点的投机重排，或在发现违规时 replay。比下一课事务内存弱：这里没有多行原子提交，只有顺序约束。")],-1)),e[5]||(e[5]=a("p",null,"relaxed 原子只保证该地址 RMW 的原子性，不提供这把「刀」。seq-cst 在所有核上插一把全序，实现上接近更重的 fence。锁的正确写法是 release 解锁、acquire 加锁，数据本身用普通访存即可——数据竞争自由程序的编译器契约。",-1)),e[6]||(e[6]=a("p",null,"第一张图画的是单核里 release 与 acquire 各自约束哪侧访存；这张图回答第二个问题：两个核对同一把锁一交一接时，配对如何把 data=1 送到下一位手里。",-1)),(o(),i(n,null,{default:s(()=>[d(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%A0%B8%20A%22%5D%20--%3E%20W%5B%22data%20%3D%201%EF%BC%8C%E6%99%AE%E9%80%9A%E5%86%99%22%5D%0A%20%20W%20--%3E%20REL%5B%22release%20%E8%A7%A3%E9%94%81%EF%BC%9A%E5%85%88%E5%89%8D%E7%9A%84%E5%86%99%E5%85%88%E5%85%A8%E5%B1%80%E5%8F%AF%E8%A7%81%22%5D%0A%20%20REL%20--%3E%20OPEN%5B%22%E9%94%81%E5%AD%97%E5%8F%98%E4%B8%BA%E5%B7%B2%E8%A7%A3%E9%94%81%22%5D%0A%20%20OPEN%20--%3E%20ACQ%5B%22%E6%A0%B8%20B%20acquire%20%E5%8A%A0%E9%94%81%E6%88%90%E5%8A%9F%22%5D%0A%20%20ACQ%20--%3E%20R%5B%22%E8%AF%BB%20data%EF%BC%9A%E4%BF%9D%E8%AF%81%E7%9C%8B%E5%88%B0%201%22%5D%0A"})]),fallback:s(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=t('<p><span class="marginnote">常见误区：初学者容易把 relaxed 原子当成「又便宜又安全」的万能药。relaxed 只保证那一个地址自身的读改写不被切开，跨地址的先后完全不管——拿它保护共享数据，上面「读到 0」的事故照样发生。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 C++ 的 memory_order 矩阵整页抄来。也不把 Linux <code>smp_mb</code> 的各种变体列全。事务内存试图把临界区里的多行读写作一个原子块，失败则 abort，下一课。fence 指令的微结构代价再下一课单独记账。</p><p>后课默认：锁配对用 acquire/release 即可表达可见性，不必每条访存 seq-cst。把整个临界区包成硬件事务是另一条路。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>acquire/release 是单向屏障，服务锁的可见性，弱于全序 fence。</li><li>实现上主要约束 SQ drain 与后续访存的发射。</li><li>多行投机原子块是下一课事务内存。</li><li>出处：Boehm and Adve, <em>PLDI</em>, 2008；SPARC RMO；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',6))])}const _=c(p,[["render",u]]);export{C as __pageData,_ as default};
